17	package org.apache.kafka.streams.kstream.internals;
18	
19	import org.apache.kafka.common.utils.Bytes;
20	import org.apache.kafka.streams.kstream.EmitStrategy;
21	import org.apache.kafka.streams.kstream.Windows;
22	import org.apache.kafka.streams.state.DslWindowParams;
