31	public class SlidingWindowStoreMaterializer<K, V> extends MaterializedStoreFactory<K, V, WindowStore<Bytes, byte[]>> {
32	
33	    private final SlidingWindows windows;
34	    private final EmitStrategy emitStrategy;
35	    private final long retentionPeriod;
36	
37	    public SlidingWindowStoreMaterializer(
38	            final MaterializedInternal<K, V, WindowStore<Bytes, byte[]>> materialized,
39	            final SlidingWindows windows,
40	            final EmitStrategy emitStrategy
41	    ) {
42	        super(materialized);
43	        this.windows = windows;
44	        this.emitStrategy = emitStrategy;
45	
46	        retentionPeriod = retentionPeriod();
47	        // large retention time to ensure that all existing windows needed to create new sliding windows can be accessed
48	        // earliest window start time we could need to create corresponding right window would be recordTime - 2 * timeDifference
49	        if ((windows.timeDifferenceMs() * 2 + windows.gracePeriodMs()) > retentionPeriod) {
50	            throw new IllegalArgumentException("The retention period of the window store "
51	                    + materialized.storeName()
52	                    + " must be no smaller than 2 * time difference plus the grace period."
53	                    + " Got time difference=[" + windows.timeDifferenceMs() + "],"
54	                    + " grace=[" + windows.gracePeriodMs() + "],"
55	                    + " retention=[" + retentionPeriod + "]");
56	        }
57	    }
58	
59	    @Override
60	    public StoreBuilder<?> builder() {
61	        final WindowBytesStoreSupplier supplier = materialized.storeSupplier() == null
62	                ? dslStoreSuppliers().windowStore(new DslWindowParams(
63	                        materialized.storeName(),
64	                        Duration.ofMillis(retentionPeriod),
65	                        Duration.ofMillis(windows.timeDifferenceMs()),
66	                        false,
67	                        emitStrategy,
68	                        true,
69	                        true
70	                ))
71	                : (WindowBytesStoreSupplier) materialized.storeSupplier();
72	
73	        final StoreBuilder<TimestampedWindowStore<K, V>> builder = Stores
74	                .timestampedWindowStoreBuilder(
75	                        supplier,
76	                        materialized.keySerde(),
77	                        materialized.valueSerde()
78	                );
79	
80	        if (materialized.loggingEnabled()) {
81	            builder.withLoggingEnabled(materialized.logConfig());
82	        } else {
83	            builder.withLoggingDisabled();
84	        }
85	
86	        // do not enable cache if the emit final strategy is used
87	        if (materialized.cachingEnabled() && emitStrategy.type() != EmitStrategy.StrategyType.ON_WINDOW_CLOSE) {
88	            builder.withCachingEnabled();
89	        } else {
90	            builder.withCachingDisabled();
91	        }
92	
93	        return builder;
94	    }
95	
96	    @Override
97	    public final long retentionPeriod() {
98	        return  materialized.retention() != null
99	                ? materialized.retention().toMillis()
100	                : windows.gracePeriodMs() + 2 * windows.timeDifferenceMs();
101	    }
102	
103	    @Override
104	    public long historyRetention() {
105	        throw new IllegalStateException(
106	                "historyRetention is not supported when not a versioned store");
107	    }
108	
109	    @Override
110	    public boolean isWindowStore() {
111	        return true;
112	    }
113	
114	    @Override
115	    public boolean isVersionedStore() {
116	        return false;
117	    }
118	
119	}
